// Fabor console prototype · Collections in depth: strategy by bucket and the contact rules, the collector's case
// (LN-A-C11) with contact, promises, hardship and restructuring, the legal and write-off case (LN-A-C14), and the
// repossession case (R-A4) through notice, auction and settlement.
// The regulatory points are the prototype's reading of the rules, to be confirmed with counsel.
// Classic scripts sharing one global scope; load order is set in index.html.

/* ---------------- the contact rules every collector works within ---------------- */
const NOW = { get day() { return tt("Saturday", "วันเสาร์"); }, time: "10:52", from: "08:00", to: "18:00", weekend: true };
const CONTACT_RULES = [
  ["Hours", "เวลา", "Weekdays 08:00 to 20:00; weekends and public holidays 08:00 to 18:00", "วันทำการ 08:00 ถึง 20:00 วันหยุด 08:00 ถึง 18:00"],
  ["How often", "ความถี่", "One successful contact a day with the debtor; attempts are logged", "ติดต่อสำเร็จได้วันละหนึ่งครั้ง บันทึกทุกความพยายาม"],
  ["Who you are", "แสดงตัว", "Give your name and the bank's name; on request, the authority to collect", "แจ้งชื่อตนเองและชื่อธนาคาร และแสดงหนังสือมอบอำนาจเมื่อถูกขอ"],
  ["Third parties", "บุคคลที่สาม", "Only to find out how to reach the debtor; never mention the debt", "สอบถามเพียงวิธีติดต่อลูกหนี้ ห้ามเปิดเผยเรื่องหนี้"],
  ["Never", "ห้าม", "Threats, abusive language, misleading statements, or letters that show the debt on the envelope", "ข่มขู่ ใช้ถ้อยคำหยาบคาย ให้ข้อมูลเท็จ หรือส่งจดหมายที่เปิดเผยเรื่องหนี้บนซอง"]];

/* ---------------- LN-A-C11: Malee Wongsa, a personal loan 65 days late ---------------- */
const MAL = (() => {
  const P = 150000, rate = 0.22, r = rate / 12, n = 48, pay = 4725.91, rows = [];
  let b = P;
  for (let i = 1; i <= n; i++) { const interest = r2(b * r), principal = r2(pay - interest); b = r2(b - principal); rows.push({ n: i, due: Date.UTC(2024, 6 + i, 20), interest, principal, amount: pay, balance: b, state: i <= 24 ? "paid" : i <= 27 ? "overdue" : i === 28 ? "next" : "scheduled" }); }
  const late = rows.filter((x) => x.state === "overdue"), days = (ms) => Math.round((BIZ - ms) / 864e5);
  const defaultInt = r2(late.reduce((s, x) => s + x.principal * 0.03 / 365 * days(x.due), 0)), fees = 300, overdue = r2(late.reduce((s, x) => s + x.amount, 0));
  return { P, rate, r, n, pay, rows, late, days, principalOut: rows[23].balance, overdue, defaultInt, fees, due: r2(overdue + defaultInt + fees), dpd: days(late[0].due), npl: late[0].due + 90 * 864e5 };
})();
const MALC = { rpcToday: 0, log: [[Date.UTC(2026, 9, 24), "08:15", "SMS", tt("Reminder: 3 instalments overdue", "แจ้งเตือน: ค้าง 3 งวด"), "", "done"], [Date.UTC(2026, 9, 23), "18:40", tt("Call, mobile", "โทร มือถือ"), tt("No answer", "ไม่มีผู้รับสาย"), "Nok S.", ""], [Date.UTC(2026, 9, 21), "10:05", tt("Call, mobile", "โทร มือถือ"), tt("Spoke to Malee: hours cut at work; promised ฿5,000 by 31 Oct", "คุยกับคุณมาลี: ถูกลดชั่วโมงงาน นัดชำระ ฿5,000 ภายใน 31 ต.ค."), "Nok S.", "done"], [Date.UTC(2026, 9, 2), "—", tt("Letter 1", "จดหมายฉบับที่ 1"), tt("To the registered address, plain envelope", "ส่งตามที่อยู่ทะเบียน ซองไม่ระบุเรื่องหนี้"), "", "done"]],
  promises: [[Date.UTC(2026, 9, 21), [[Date.UTC(2026, 9, 31), 5000]], "open"], [Date.UTC(2026, 8, 3), [[Date.UTC(2026, 8, 10), 4725.91]], "broken"]], hs: { reason: "income", since: "2026-08-01", before: "28000", now: "17500", expenses: "9800", evidence: ["employer"] }, offer: null, accepted: false };
const HARDSHIP_REASONS = [["income", "Income cut or lost hours", "รายได้ลดหรือถูกลดชั่วโมงงาน"], ["job", "Lost job", "ตกงาน"], ["illness", "Illness or injury", "เจ็บป่วยหรือบาดเจ็บ"], ["family", "Death or illness in the family", "ครอบครัวเสียชีวิตหรือเจ็บป่วย"], ["disaster", "Flood or other disaster", "น้ำท่วมหรือภัยพิบัติ"], ["business", "Business income fell", "รายได้จากกิจการลดลง"]];
function hsCalc() {
  const h = MALC.hs, now = num(h.now), exp = num(h.expenses), other = 1800, spare = Math.max(0, now - exp - other), affordable = Math.floor(spare * 0.7 / 10) * 10;
  const bal = r2(MAL.principalOut + MAL.late.reduce((s, x) => s + x.interest, 0) + MAL.defaultInt), base = MAL.n - 24;
  const opt = (k, en, th, months, rate, holiday, desc) => { const r = rate / 12, capital = holiday ? r2(bal * Math.pow(1 + r, holiday)) : bal, inst = r2(pmt(r, months, capital)), total = r2(inst * months);
    let pv = 0; for (let i = 1; i <= months; i++) pv += inst / Math.pow(1 + MAL.r, i + holiday); return { k, en, th, months, rate, holiday, desc, inst, total, interest: r2(total - capital), mod: Math.abs(pv - bal) < 1 ? 0 : r2(pv - bal), fits: inst <= affordable }; };
  const opts = [opt("extend", "Extend the term", "ขยายระยะเวลา", 60, MAL.rate, 0, ["Arrears added to the balance; 60 months at 22%", "ทบยอดค้างเข้าเงินต้น 60 เดือน ที่ 22%"]),
    opt("holiday", "Three months' pause, then extend", "พัก 3 เดือน แล้วขยายระยะ", 57, MAL.rate, 3, ["Nothing to pay Nov to Jan; interest accrues; then 57 months", "ไม่ต้องชำระ พ.ย. ถึง ม.ค. ดอกเบี้ยยังเดิน จากนั้น 57 เดือน"]),
    opt("rate", "Lower rate and extend", "ลดดอกเบี้ยและขยายระยะ", 60, 0.16, 0, ["16% instead of 22%, 60 months", "16% แทน 22% 60 เดือน"])];
  return { now, exp, other, spare, affordable, bal, base, opts, drop: Math.round((1 - now / num(h.before)) * 100) };
}

