    pills: lateP(MAL.dpd) + P("warn", "Stage 2") + (MALC.offer ? P("info", MALC.accepted ? tt("Restructured", "ปรับโครงสร้างแล้ว") : tt("Offer with the customer", "ส่งข้อเสนอให้ลูกค้าแล้ว")) : P("info", tt("Hardship reported", "แจ้งประสบปัญหา"))),
