document.addEventListener("input", (e) => { const k = e.target.dataset && e.target.dataset.hs; if (!k) return; MALC.hs[k] = e.target.value; const o = $("#hsOut"); if (o) o.innerHTML = hsOutHtml(hsCalc()); });
document.addEventListener("change", (e) => { const k = e.target.dataset && e.target.dataset.hsEv; if (!k) return; const ev = MALC.hs.evidence; if (e.target.checked && !ev.includes(k)) ev.push(k); if (!e.target.checked) ev.splice(ev.indexOf(k), 1); });
document.addEventListener("click", (e) => { if (e.target.closest("[data-mal-accept]")) { MALC.accepted = true; render(); } });

